class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        arr = list(nums)
        ops = 0

        while len(arr) > 1:
            if all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1)):
                return ops

            min_sum = None
            min_idx = 0
            for i in range(len(arr) - 1):
                s = arr[i] + arr[i + 1]
                if min_sum is None or s < min_sum:
                    min_sum = s
                    min_idx = i

            arr = arr[:min_idx] + [min_sum] + arr[min_idx + 2:]
            ops += 1

        return ops
