class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)
        best = 0

        # Enumerate all substrings of s (including empty substring)
        for i in range(n + 1):
            for j in range(i, n + 1):
                a = s[i:j]
                la = j - i
                # Even if we take the whole t, we cannot beat current best
                if la + m <= best:
                    continue

                # Enumerate all substrings of t (including empty substring)
                for k in range(m + 1):
                    for l in range(k, m + 1):
                        lb = l - k
                        if la + lb <= best:
                            continue
                        cand = a + t[k:l]
                        # Check palindrome
                        if cand == cand[::-1]:
                            best = la + lb

        return best
