def main():
    data = sys.stdin.read().split()
    if not data:
        return
    Q = int(data[0])
    queries = [int(x) for x in data[1:1 + Q]]

    MAX_M = 1000000  # because sqrt(10^12) = 10^6

    # smallest prime factor sieve
    spf = list(range(MAX_M + 1))
    for i in range(2, int(MAX_M ** 0.5) + 1):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, MAX_M + 1, step):
                if spf[j] == j:
                    spf[j] = i

    # number of distinct prime factors
    distinct = [0] * (MAX_M + 1)
    distinct[0] = 0
    distinct[1] = 0
    for i in range(2, MAX_M + 1):
        p = spf[i]
        if p == i:
            distinct[i] = 1
        else:
            j = i // p
            if spf[j] == p:
                distinct[i] = distinct[j]
            else:
                distinct[i] = distinct[j] + 1

    # best[m] = largest number <= m with exactly 2 distinct prime factors
    best = [0] * (MAX_M + 1)
    last = 0
    for i in range(MAX_M + 1):
        if i >= 2 and distinct[i] == 2:
            last = i
        best[i] = last

    out = []
    for A in queries:
        M = math.isqrt(A)
        if M > MAX_M:
            M = MAX_M
        m = best[M]
        out.append(str(m * m))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
