import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    R = int(data[1])
    C = int(data[2])
    S = data[3].strip()

    dr = 0
    dc = 0
    # D-values of birth times (including time 0)
    seen = {(0, 0)}
    ans = []

    for ch in S:
        if ch == 'N':
            dr -= 1
        elif ch == 'S':
            dr += 1
        elif ch == 'W':
            dc -= 1
        elif ch == 'E':
            dc += 1

        # For current time t (1-indexed), we need a birth time b < t
        # with D[b] = D[t] - (R, C)
        tr = dr - R
        tc = dc - C
        if (tr, tc) in seen:
            ans.append('1')
        else:
            ans.append('0')

        # If current position has not been a birth time, it becomes one now
        if (dr, dc) not in seen:
            seen.add((dr, dc))

    sys.stdout.write(''.join(ans))

if __name__ == '__main__':
    solve()
