from typing import List

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # We can delete any elements, so we can keep only the elements we want.
        # To maximize the sum of a subarray with all unique elements, we should
        # take every distinct positive value (each at most once).
        # If there are no positive numbers, we must keep at least one element,
        # so we take the maximum element (which could be zero or negative).

        positive_set = set()
        max_val = nums[0]
        for x in nums:
            if x > 0:
                positive_set.add(x)
            if x > max_val:
                max_val = x

        if positive_set:
            return sum(positive_set)
        return max_val
