from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # Precompute powers of 4 up to > 2e9
        pow4 = [1]
        while pow4[-1] <= 2_000_000_000:
            pow4.append(pow4[-1] * 4)
        # pow4[i] = 4^i, pow4[0] = 1, pow4[1] = 4, ...

        # g(x) = number of times we can apply floor division by 4 to reach 0
        def g(x: int) -> int:
            if x == 0:
                return 0
            for k in range(1, len(pow4)):
                if x < pow4[k]:
                    return k
            return len(pow4) - 1  # fallback, should not happen for given constraints

        # G(n) = sum_{x=1}^{n} g(x)
        def G(n: int) -> int:
            if n == 0:
                return 0
            total = 0
            for k in range(1, len(pow4)):
                low = pow4[k - 1]
                high = pow4[k] - 1
                if n <= high:
                    total += k * (n - low + 1)
                    break
                else:
                    total += k * (high - low + 1)
            return total

        ans_sum = 0
        for l, r in queries:
            total = G(r) - G(l - 1)
            max_h = g(r)          # g is non-decreasing, so max on [l, r] is g(r)
            ops = max(max_h, (total + 1) // 2)
            ans_sum += ops

        return ans_sum
