from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        # Segment tree storing maximum available capacity in each segment
        tree = [0] * (4 * n)

        def build(node: int, l: int, r: int) -> None:
            if l == r:
                tree[node] = baskets[l]
                return
            mid = (l + r) // 2
            build(node * 2, l, mid)
            build(node * 2 + 1, mid + 1, r)
            tree[node] = max(tree[node * 2], tree[node * 2 + 1])

        def update(node: int, l: int, r: int, idx: int, val: int) -> None:
            if l == r:
                tree[node] = val
                return
            mid = (l + r) // 2
            if idx <= mid:
                update(node * 2, l, mid, idx, val)
            else:
                update(node * 2 + 1, mid + 1, r, idx, val)
            tree[node] = max(tree[node * 2], tree[node * 2 + 1])

        def query(node: int, l: int, r: int, x: int) -> int:
            """Return leftmost index in [l, r] with capacity >= x, or -1 if none."""
            if tree[node] < x:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            if tree[node * 2] >= x:
                return query(node * 2, l, mid, x)
            return query(node * 2 + 1, mid + 1, r, x)

        build(1, 0, n - 1)
        unplaced = 0

        for f in fruits:
            idx = query(1, 0, n - 1, f)
            if idx == -1:
                unplaced += 1
            else:
                # Mark basket as used (capacity becomes -1 so it won't be chosen again)
                update(1, 0, n - 1, idx, -1)

        return unplaced
